      "skillsData": {
        "wz26.jiangwei.kunfen": {
          "name": "wz26.jiangwei.kunfen",
          "lang_name": "困奋",
          "lang_desc": "结束阶段，你可以失去1点体力，然后摸两张牌（修改：增加描述“且可以视为使用一张【火攻】”）。",
          "lang_desc2": "",
          "audios": [
            {
              "url": "generals/jiangwei/sp.jiangwei/kunfen1",
              "translation": "纵 使困顿难行，亦当砥砺奋进！"
            },
            {
              "url": "generals/jiangwei/sp.jiangwei/kunfen2",
              "translation": "兴蜀需时，众将切勿惫怠！"
            }
          ]
        },
        "wz26.jiangwei.fengliang": {
          "name": "wz26.jiangwei.fengliang",
          "lang_name": "逢亮",
          "lang_desc": "觉醒技，当你进入濒死状态时，你减1点体力上限并将体力回复至2点，然后获得“挑衅”，并修改“困奋”。",
          "lang_desc2": "",
          "audios": [
            {
              "url": "generals/jiangwei/sp.jiangwei/fengliang1",
              "translation": "得遇丞相，再生之德！"
            },
            {
              "url": "generals/jiangwei/sp.jiangwei/fengliang2",
              "translation": "丞相大义，维岂有不从之理！"
            }
          ]
        },
        "wz26.jiangwei.tiaoxin": {
          "name": "wz26.jiangwei.tiaoxin",
          "lang_name": "挑衅",
          "lang_desc": "出牌阶段限一次，你可以令一名其他角色选择一项：1.对你使用一张【杀】；2.你弃置其一张牌。",
          "lang_desc2": "",
          "audios": [
            {
              "url": "generals/jiangwei/sp.jiangwei/tiaoxin1",
              "translation": "今日天公作美，怎能不战而退？"
            },
            {
              "url": "generals/jiangwei/sp.jiangwei/tiaoxin2",
              "translation": "贼将无胆，何不早降！"
            }
          ]
        }
      },
