      "asset": {
        "info": {
          "id": "WEI075",
          "title": "锋镝悬信",
          "prefix": "竞",
          "designer": "韩旭",
          "script": "归零"
        },
        "skins": [
          {
            "name": "default",
            "painter": "biou09",
            "cv": "未知",
            "audios": {
              "death": {
                "translation": "丞相，再给我一次机会啊！"
              }
            }
          }
        ]
      },
      "skillsData": {
        "wz26.jianggan.weicheng": {
          "name": "wz26.jianggan.weicheng",
          "lang_name": "伪诚",
          "lang_desc": "当你将手牌交给其他角色，或你的手牌被其他角色获得后，若你的手牌数不大于体力值，你可以摸一张牌。",
          "lang_desc2": "当其他角色因获得或你交给其牌 后，若你的手牌数不大于体力值，你可摸一张牌。",
          "audios": [
            {
              "url": "generals/jianggan/weicheng1",
              "translation": "略施谋略，敌 军便信以为真。"
            },
            {
              "url": "generals/jianggan/weicheng2",
              "translation": "吾只观雅规，而非说客。"
            }
          ]
        },
        "wz26.jianggan.daoshu": {
          "name": "wz26.jianggan.daoshu",
          "lang_name": "盗书",
          "lang_desc": "出牌阶段限一次，你可以选择一名其他角色并选择一种花色，然后获得其一张手牌。\n若此牌与你选择的花色相同，你对其造成1点伤害且此技能视为未发动过；\n不同，你交给其一张其他花色的手牌（若没有须展示所有手牌）。",
          "lang_desc2": "出牌阶段限一次，你可选择一名有手牌的其他角色并选择一种花色▶你获得其一张手牌。若该牌 与你选择的花色相同，你对其造成1点普通伤害，并重置〖盗书〗使用次数；若不同，若你有其他花色手牌，可交给其一张不同花色手牌；若没有，则展示所有手牌。",
          "audios": [
            {
              "url": "generals/jianggan/daoshu1",
              "translation": "得此文书，丞相定可高枕无忧。"
            },
            {
              "url": "generals/jianggan/daoshu2",
              "translation": "让我看看，这是什么机密。"
            }
          ]
        },
        "wz26.jianggan.daizui": {
          "name": "wz26.jianggan.daizui",
          "lang_name": "戴罪",
          "lang_desc": "限定技，当你受到致命伤害时，你可以对伤害来源发动一次“盗书”，若本次“盗书”你对 其造成了伤害，则防止你受到的致命伤害。",
          "lang_desc2": "出牌阶段限一次，你可选择一名有手牌的其他角色并选择一种花色▶你获得 其一张手牌。若该牌与你选择的花色相同，你对其造成1点普通伤害，并重置〖盗书〗使用次数；若不同，若你有其他花色手牌，可交给其一张不同花色手牌；若没有，则展示所有手牌。",
          "audios": [
            {
              "url": "generals/jiagngan/mobile.jianggan/daizui1",
              "translation": " 望丞相权且记过，容干将功折罪啊！"
            },
            {
              "url": "generals/jianggan/mobile.jianggan/daizui2",
              "translation": "干谢丞相不杀之恩！"
            }
          ]
        }
      },
