      "skillsData": {
        "wars.lord_liubei.shouyue": {
          "name": "wars.lord_liubei.shouyue",
          "lang_name": "授钺",
          "lang_desc": "君主技，你拥有“五虎将大旗”。",
          "lang_desc2": "锁定技，你拥有〖五虎将大 旗〗。",
          "audios": [
            {
              "url": "generals/lord_liubei/shouyue",
              "translation": "布德而昭仁，见旗如见朕!"
            }
          ]
        },
        "wars.lord_liubei.wuhujiangdaqi": {
          "name": "wars.lord_liubei.wuhujiangdaqi",
          "lang_name": "五虎将大旗",
          "lang_desc": "存活的蜀势力角色技能分别按以 下调整：\n武圣——将“红色牌”改为“任意牌”。\n咆哮——增加描述“你使用【杀】无视其他角色防具。”\n龙胆——增加描述“当 你以此法使用或打出牌时，你摸一张牌。”\n烈弓——增加描述“你的攻击范围+1。”\n铁骑——将“一张明置武将牌的非锁定技失效” 改为“所有明置武将牌的非锁定技失效”。",
          "lang_desc2": "存活的蜀势力角色的技能改造描述（略长，可按原文复制）。",
          "audios": []
        },
        "wars.lord_liubei.zhangwu": {
          "name": "wars.lord_liubei.zhangwu",
          "lang_name": "章武",
          "lang_desc": "锁定技，当【飞龙夺凤】进 入弃牌堆或其他角色的装备区后，你获得之。当你失去【飞龙夺凤】前，你展示之，然后将此牌置于牌堆底并摸两张牌。",
          "lang_desc2": "锁定技，当【飞龙夺凤】移至弃牌堆或其他角色装备区后❷，你获得此牌▶失去前展示并置于牌堆底，摸两张牌。",
          "audios": [
            {
              "url": "generals/lord_liubei/zhangwu1",
              "translation": "遁剑归一，有凤来仪。"
            },
            {
              "url": "generals/lord_liubei/zhangwu2",
              "translation": "剑气化龙，听朕雷动！"
            }
          ]
        },
        "wars.lord_liubei.jizhao": {
          "name": "wars.lord_liubei.jizhao",
          "lang_name": "激诏",
          "lang_desc": "限定技，当你濒死时，你可将手牌补至体力上限，然后体力回复至2，失去“授钺”，获得“仁德”。",
          "lang_desc2": "限定技，当你濒死时，补手牌至体力上限▶体力至2，失去〖授钺〗并获得〖仁德〗。",
          "audios": [
            {
              "url": "generals/lord_liubei/jizhao1",
              "translation": "仇未报，汉未兴，朕志犹在！"
            },
            {
              "url": "generals/lord_liubei/jizhao2",
              "translation": "王业不偏安，起师再兴汉！"
            }
          ]
        },
        "wars.lord_liubei.rende": {
          "name": "wars.lord_liubei.rende",
          "lang_name": "仁德",
          "lang_desc": "出牌阶段每名角色限一次，你可将任意张手牌交给一名角色，当你给出第二张牌时，可视为使用一张基本牌。",
          "lang_desc2": "出牌阶段，将至少一张手牌交给一名角色▶若交出第 二张牌，可视为使用一张基本牌。",
          "audios": [
            {
              "url": "generals/lord_liubei/rende1",
              "translation": "勿以恶小而为之，勿以善小而 不为。"
            },
            {
              "url": "generals/lord_liubei/rende2",
              "translation": "君才十倍于丕，必能安国成事。"
            }
          ]
        }
      },
