      "skillsData": {
        "wars.lord_simayi.jiaping": {
          "name": "wars.lord_simayi.jiaping",
          "lang_name": "嘉平",
          "lang_desc": "君主技，你拥有“八荒死士令”。",
          "lang_desc2": "锁定技，你拥有〖八荒死士令〗。",
          "audios": [
            {
              "url": "generals/lord_simayi/jiaping",
              "translation": "藏锋四十载，终昭吾亮剑之时！"
            }
          ]
        },
        "wars.lord_simayi.bahuangsishiling": {
          "name": "wars.lord_simayi.bahuangsishiling",
          "lang_name": "八荒死士令",
          "lang_desc": "每轮限一次，每名晋势力角色的出牌阶段，若其于此轮内明置过武将牌，其可移除副将的武将牌，然后从“瞬覆”、“奉迎”、“将略”、“勇进”、“乱武”中选择并发动一个未以此法选择过 的技能。",
          "lang_desc2": "①晋势力角色的出牌阶段，若其于此轮内明置过武将牌且此技能在本轮未发动，其可移除副将武将牌并选择至 多三名没有势力的角色▶这些角色各摸两张牌，可使用【杀】（无距离限制）。\n◆因此效果使用的【杀】不是牌的合法目标。\n②晋势 力角色的出牌阶段，若其明置过武将牌且技能未发动，可移除副将▶其可令其他角色依次使用【杀】，否则失去1点体力。\n③限定技，可选择军令▶与你势力相同的角色各选择是否执行，回复体力并摸牌。\n④可移动其他角色装备区的牌。\n⑤使用【挟天子以令诸侯】时， 可将副将移除，按规则补手牌。",
          "audios": []
        },
        "wars.lord_simayi.guikuang": {
          "name": "wars.lord_simayi.guikuang",
          "lang_name": " 诡诳",
          "lang_desc": "出牌阶段限一次，你可以令两名角色拼点（不能为两名势力相同的角色），拼点牌为红色的角色依次对拼点没赢的角色造成1点伤害。",
          "lang_desc2": "出牌阶段限一次，你可选择不为势力相同的两名角色并令这两名角色拼点▶所有拼点牌为红色的角色各对所有未赢的角色造成1点普通伤害。",
          "audios": [
            {
              "url": "generals/lord_simayi/guikuang1",
              "translation": "数载春去秋来，静看大 江东流。"
            },
            {
              "url": "generals/lord_simayi/guikuang2",
              "translation": "吞吴克蜀，老臣毕生之志也。"
            }
          ]
        },
        "wars.lord_simayi.shujuan": {
          "name": "wars.lord_simayi.shujuan",
          "lang_name": "舒卷",
          "lang_desc": "锁定技，【戢鳞潜翼】每回合首次被置入弃牌堆或其他角 色的装备区后，你获得并使用之。",
          "lang_desc2": "锁定技，当【戢鳞潜翼】移至弃牌堆或他人装备区后，若本回合未获得同名牌，你获 得此牌并使用。",
          "audios": [
            {
              "url": "generals/lord_simayi/shujuan1",
              "translation": "戢鳞潜翼，蓄志待时。"
            },
            {
              "url": "generals/lord_simayi/shujuan2",
              "translation": "坐观潮起潮落，笑谈云卷云舒。"
            }
          ]
        },
        "wars.lord_simayi.shunfu": {
          "name": "wars.lord_simayi.shunfu",
          "lang_name": "瞬覆",
          "lang_desc": "限定技，出牌阶段，你可令至多三名未确定势力的其他角色各摸两张牌，然后这些角色依 次选择是否使用一张无距离限制且不可响应的【杀】。",
          "lang_desc2": "限定技，出牌阶段，你可选择至多三名没有势力的其他角色▶这 些角色各摸两张牌，可使用【杀】（无距离限制），使用的【杀】不是牌的合法目标。",
          "audios": [
            {
              "url": "generals/lord_simayi/shunfu",
              "translation": "天地造化，不过老夫一念之间！"
            }
          ]
        },
        "wars.lord_simayi.fengying": {
          "name": "wars.lord_simayi.fengying",
          "lang_name": "奉迎",
          "lang_desc": "限定技，出牌阶段，你可以将所有手牌当做【挟天子以令诸侯】无视条件使用，令所有与你势力相同的角色将手牌摸至其体力上限。",
          "lang_desc2": "限定技，当你使用【挟天子以令诸侯】时，你可将手牌视作【挟天子以令诸侯】▶所有与你 势力相同的角色将手牌补至体力上限。",
          "audios": [
            {
              "url": "generals/lord_simayi/fengying",
              "translation": "臣当总领西事，不负陛 下所托。"
            }
          ]
        },
        "wars.lord_simayi.jianglue": {
          "name": "wars.lord_simayi.jianglue",
          "lang_name": "将略",
          "lang_desc": "限定技，出牌阶段，你可以选择一个“军令”，与你势力相同的其他角色均可执行该军令。你和每一个执行军令的角色体力上限+1（不能大于5）且回复1点体力，然后你摸X张牌（X为执行此军令的人数+1）。",
          "lang_desc2": "限定技，出牌阶段，你可选择军令▶与你势力相同的其他角色各选择是否执行▶你和执行的角色各加1点体力上限并回复1点体力，你摸X张牌（X为执行军令的角色数+1）。",
          "audios": [
            {
              "url": "generals/lord_simayi/jianglue",
              "translation": "能战当战，不能战，当死耳！"
            }
          ]
        },
        "wars.lord_simayi.yongjin": {
          "name": "wars.lord_simayi.yongjin",
          "lang_name": "勇进",
          "lang_desc": "限定技，出牌阶段，你可以依次移动场上的至多三张装备牌。",
          "lang_desc2": "限定技，出牌阶段，你可将一名角色装备区的牌移动至另一角色装备区，可最多移动三张牌。",
          "audios": [
            {
              "url": "generals/lord_simayi/yongjin",
              "translation": "连下诸城以筑京观，足永平辽东之患！"
            }
          ]
        },
        "wars.lord_simayi.luanwu": {
          "name": "wars.lord_simayi.luanwu",
          "lang_name": "乱武",
          "lang_desc": "限定技，出牌阶段，你可以令所有其他角色依次选择一项：1.对距离最近的另一名角色使用一张【 杀】；2.失去1点体力。",
          "lang_desc2": "限定技，出牌阶段，你可选择所有其他角色▶这些角色各需对包括距离最小的另一名角色使用【杀】，否则失去1点体力。",
          "audios": [
            {
              "url": "generals/lord_simayi/luanwu",
              "translation": "连诛其族，翦其党羽，以夷后患！"
            }
          ]
        }
      },
