      "skillsData": {
        "xl.shibao.yuanliang": {
          "name": "xl.shibao.yuanliang",
          "lang_name": "远量",
          "lang_desc": "当你摸牌时，你可以令摸牌数+1，并 移存此次摸牌的其中一张。出牌阶段限一次，当你使用基本牌或普通锦囊牌选择一名其他角色为唯一目标时，你可以弃置后备区里的一张 点数相同的牌，令此牌造成的伤害值+1，或令此牌描述中除目标数外的一个数值+1。",
          "lang_desc2": "",
          "audios": [
            {
              "url": "generals/xl/xl.shibao/yuanliang1",
              "translation": "出身寒门，亦有凌空远志。"
            },
            {
              "url": "generals/xl/xl.shibao/yuanliang2",
              "translation": "巢中幼雏，定有冲天之时。"
            }
          ]
        },
        "xl.shibao.zaoshi": {
          "name": "xl.shibao.zaoshi",
          "lang_name": "造势",
          "lang_desc": "当你首次明置 此武将牌时，若你不为野心家势力，你可以选择一个势力。本局游戏中，当此势力满足大势力条件时，你将你的势力改为唯一的大势力。",
          "lang_desc2": "",
          "audios": [
            {
              "url": "generals/xl/xl.shibao/zaoshi1",
              "translation": "大魏历数已终，陛下逊位，后世必称其明。"
            },
            {
              "url": "generals/xl/xl.shibao/zaoshi2",
              "translation": "愿陛下礼行禅让，以成唐虞之美。"
            }
          ]
        }
      },
