          "skillsData": {
            "wz26.zhangchunhua.jueqing": {
              "name": "wz26.zhangchunhua.jueqing",
              "lang_name": "绝情",
              "lang_desc": "当你造成非传导伤害时，你可以失去等量的体力并令此伤害翻倍。若如此做，此伤害结算完成后，你修改“绝情”。（修改：锁定技，你即将造成的伤害 视为失去体力。）",
              "lang_desc2": "",
              "audios": [
                {
                  "url": "generals/zhangchunhua/jueqing1",
                  "translation": "无情者伤人，有情者自伤。"
                },
                {
                  "url": "generals/zhangchunhua/jueqing2",
                  "translation": "你的死活，与我何干？"
                }
              ]
            },
            "wz26.zhangchunhua.shangshi": {
              "name": "wz26.zhangchunhua.shangshi",
              "lang_name": "伤逝",
              "lang_desc": "当你的手牌数小于X时，你可以将手牌摸至X张(X为你已损失的体力 值)。",
              "lang_desc2": "",
              "audios": [
                {
                  "url": "generals/zhangchunhua/shangshi1",
                  "translation": "自戕于此，无哀无伤。"
                },
                {
                  "url": "generals/zhangchunhua/shangshi2",
                  "translation": "身伤易愈，心伤难合。"
                }
              ]
            },
            "wz26.zhangchunhua.jianmie": {
              "name": "wz26.zhangchunhua.jianmie",
              "lang_name": "翦灭",
              "lang_desc": "限定技，出牌阶段，你可以令一名其他角色选择一种颜色，然后你选择一种颜色，你与其展示所有手牌并弃置各自所选颜色的全部手牌(没有该颜色则不弃)，然后弃置牌较多的角色视为对另一名角色使用一张【决斗】。",
              "lang_desc2": "",
              "audios": [
                {
                  "url": "generals/zhangchunhua/jianmie1",
                  "translation": "斩草除根，以绝后患！"
                },
                {
                  "url": "generals/zhangchunhua/jianmie2",
                  "translation": "挡我者，杀无赦！"
                }
              ]
            }
          },
