          "skillsData": {
            "xl.yanghu.deshao": {
              "name": "xl.yanghu.deshao",
              "lang_name": "德劭",
              "lang_desc": "当你抵消其他角色使用的牌或你使用的牌被其他角色抵消后，你可以移存被抵消的牌，然后若你没有“阴阳鱼”标记，你可以获得一个“阴阳鱼”标记。",
              "lang_desc2": "",
              "audios": [
                {
                  "url": "generals/xl/xl.yanghu/deshao1",
                  "translation": "吴有江南已历三世，不可 急图。"
                },
                {
                  "url": "generals/xl/xl.yanghu/deshao2",
                  "translation": "公赠以木桃，我报以琼瑶。"
                }
              ]
            },
            "xl.yanghu.xuantao": {
              "name": "xl.yanghu.xuantao",
              "lang_name": "宣讨",
              "lang_desc": "每轮限一次，一名与你势力不同的角色的出牌阶段开始时，你可以弃置一张牌，然后弃置后备区里一张能造成伤害的牌，视为仅对其使用此牌；当你以此法造成伤害后，你摸一张牌，否则此技能视为未发动过。",
              "lang_desc2": "",
              "audios": [
                {
                  "url": "generals/xl/xl.yanghu/xuantao1",
                  "translation": "先声夺人，一举克定西陵！"
                },
                {
                  "url": "generals/xl/xl.yanghu/xuantao2",
                  "translation": "吾闻兵有拙速，不贵工迟也。"
                }
              ]
            },
            "xl.yanghu.chonge": {
              "name": "xl.yanghu.chonge",
              "lang_name": "冲轭",
              "lang_desc": "阵法技，当一名与你处于同一队列的角色成为【决斗】或【杀】的目标后，其可以打出一张相同花色的手牌抵消之。",
              "lang_desc2": "",
              "audios": [
                {
                  "url": "generals/xl/xl.yanghu/chonge1",
                  "translation": "昔伯舆凿运以通军道，吾当随之。"
                },
                {
                  "url": "generals/xl/xl.yanghu/chonge2",
                  "translation": "荆襄水陆阡陌，正宜左右相协。"
                }
              ]
            }
          },
